    separators = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    if not separators:
        return out
    sep = separators[0]
    top_rows = [r for r in range(sep) if any(grid[r][c] != 0 for c in range(w))]
